}

/* 顶部 Header */
.header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 2%; 
  transform: translateY(-4px); /* 【新增】整体向上移动 2px */
}

.search-icon {
  width: clamp(14px, 4.5vw, 18px);
  height: clamp(14px, 4.5vw, 18px);
  cursor: pointer; 
}

