  margin-bottom: 1px; 
  font-weight: 500;
  letter-spacing: 0.5px; /* 【调整】缩小字间距 (原为 1px) */
}

/* 底部真实日期 */
.date {
  font-size: clamp(10px, 3vw, 14px);
  color: #ffffff; 
  font-weight: bold; 
}

/* === 贴图区域 === */

/* 顶部绷带容器 (包含3个绷带) */
