/* 爱心动画样式 */
.like-heart-animation {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0);
  width: 80px;
  height: 80px;
  fill: #e0245e;
  opacity: 0;
  pointer-events: none; 
}

.like-heart-animation.animate {
  animation: pop-heart 0.7s cubic-bezier(0.18, 0.89, 0.32, 1.28); 
}

