body { 
  margin: 0; padding: 0; display: flex;
  align-items: center; justify-content: center;
  background: transparent;
}

.widget-wrapper { width: 96%; height: 96%; position: relative; }

.art-canvas {
  width: 100%; height: 100%;
  background-color: #a0a0a0;
  position: relative;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(to bottom,
    black 0%, black 66%,                 
    transparent 66%, transparent 67.5%,  
    rgba(0,0,0,0.8) 67.5%, rgba(0,0,0,0.8) 72.5%, 
    transparent 72.5%, transparent 74.5%,
    rgba(0,0,0,0.6) 74.5%, rgba(0,0,0,0.6) 78.5%, 
    transparent 78.5%, transparent 81%,  
    rgba(0,0,0,0.4) 81%, rgba(0,0,0,0.4) 84%,     
    transparent 84%, transparent 87.5%,  
    rgba(0,0,0,0.2) 87.5%, rgba(0,0,0,0.2) 89.5%, 
    transparent 89.5%, transparent 94%,  
    rgba(0,0,0,0.08) 94%, rgba(0,0,0,0.08) 95%,   
    transparent 95%, transparent 100%    
  );
}

.glitch-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  width: 100%; height: 100%;
}

.tile {
  background-image: url({{bg}});
  background-size: 300% 300%;
  transition: all 0.3s ease;
}

.t1 { background-position: 0% 0%; }
.t2 { background-position: 50% 0%; }
.t3 { background-position: 100% 0%; }
.t4 { background-position: 0% 50%; }
.t5 { background-position: 50% 50%; } 
.t6 { background-position: 100% 50%; }
.t7 { background-position: 0% 100%; }
.t8 { background-position: 50% 100%; }
.t9 { background-position: 100% 100%; }

/* --- 故障藝vv術加工 --- */

.t2 { transform: translateX(-15px); }

/* 錯ii位彩色條！ */
.t3 { position: relative; }
.t3::before, .t3::after {
  content: ""; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-image: inherit; background-size: inherit; background-position: inherit;
}
/* 上方桃紅色錯nn位條 */
.t3::before {
  transform: translateX(-12px); /* 向左錯位 */
  filter: hue-rotate(300deg) saturate(2.5) brightness(1.1); /* 轉成桃紅色 */
  clip-path: polygon(0 10%, 100% 10%, 100% 25%, 0 25%);
}
/* 下方螢光綠錯oo位條 */
.t3::after {
  transform: translateX(15px); /* 向右錯位 */
  filter: hue-rotate(120deg) saturate(2) brightness(1.2); /* 轉成螢光綠 */
  clip-path: polygon(0 70%, 100% 70%, 100% 85%, 0 85%);
}

/* 錯位vv彩色條（青藍 + 紫紅） */
.t4 { position: relative; transform: translateX(4px); }
.t4::before, .t4::after {
  content: ""; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-image: inherit; background-size: inherit; background-position: inherit;
}
.t4::before {
  transform: translateX(18px); 
  filter: hue-rotate(180deg) saturate(2) brightness(1.1); 
  clip-path: polygon(0 20%, 100% 20%, 100% 40%, 0 40%);
}
.t4::after {
  transform: translateX(-14px); 
  filter: hue-rotate(-90deg) saturate(2) brightness(1.1); 
  clip-path: polygon(0 65%, 100% 65%, 100% 80%, 0 80%);
}

.t5 { mix-blend-mode: screen; background-color: rgba(0, 100, 255, 0.2); transform: scale(1.03); }
.t6 { transform: translate(15px, 8px); }

/* 錯位彩色oo條（黃綠 + 藍） */
.t8 { position: relative; }
.t8::before, .t8::after {
  content: ""; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-image: inherit; background-size: inherit; background-position: inherit;
}
.t8::before {
  transform: translateX(-16px); 
  filter: hue-rotate(90deg) saturate(1.5) brightness(1.2); 
  clip-path: polygon(0 15%, 100% 15%, 100% 30%, 0 30%);
}
.t8::after {
  transform: translateX(12px); 
  filter: hue-rotate(200deg) saturate(2.5) brightness(1); 
  clip-path: polygon(0 55%, 100% 55%, 100% 75%, 0 75%);
}

.t9 { transform: translate(-10px, -15px); filter: saturate(0.2); }

/* 橫向v撕裂線 */
.tear-line {
  position: absolute; height: 2px; width: 120%;
  background-image: url({{bg}}); background-size: cover; z-index: 1;
}
#tear1 { top: 25%; left: -10%; background-position: 0 40%; transform: translateX(20px); filter: hue-rotate(90deg); }
#tear2 { top: 60%; left: -5%; background-position: 0 80%; transform: translateX(-15px); }

/* 噪點與選項ino層保持不變 */
.noise-overlay { position: absolute; top: 0; left: 0; right: 0; bottom: 0; pointer-events: none; z-index: 2; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E"); opacity: 0.15; mix-blend-mode: overlay; }
.noise-overlay::after { content: ""; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: repeating-linear-gradient(to bottom, transparent 0px, transparent 2px, rgba(0,0,0,0.08) 2px, rgba(0,0,0,0.08) 4px), radial-gradient(circle at center, transparent 50%, rgba(0,0,0,0.6) 120%); }
.options-container { position: absolute; top: 18%; width: 100%; display: flex; flex-direction: column; gap: 16px; z-index: 3; }
.opt-line { padding: 6px 0; text-align: center; font-family: "STZhongsong", "SimSun", "Times New Roman", serif; font-size: 13px; letter-spacing: 6px; color: rgba(255, 255, 255, 0.85); background: linear-gradient(90deg, transparent 0%, rgba(15, 20, 25, 0.45) 20%, rgba(15, 20, 25, 0.45) 80%, transparent 100%); backdrop-filter: blur(3px); cursor: pointer; transition: all 0.3s ease; text-shadow: -2px 0px 1px rgba(0, 255, 255, 0.6), 2px 0px 1px rgba(255, 0, 128, 0.6), 0px 0px 4px rgba(255, 255, 255, 0.4); animation: floatDream 4s ease-in-out infinite; }
.opt-line:nth-child(2) { animation-delay: -1.5s; }
.opt-line:nth-child(3) { animation-delay: -3s; }
.opt-line:active { transform: scale(0.95); filter: invert(1); }
@keyframes floatDream { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-2px); } }

/* ================= 基础设定 ================= */
.mz-post-widget {
  width: 100%; height: 100%; position: relative;
