/* ================= 顶端：标签栏区 ================= */
.header-zone {
  display: flex; 
  justify-content: space-between; 
  align-items: flex-end;
  height: auto; 
  position: relative; 
  z-index: 20; 
  padding: 0 8px 0 4px; /* 极小边距，确保和左侧白板边缘对齐 */
  margin-bottom: 0; 
  width: 100%; 
  box-sizing: border-box;
}

.stats-group {
  display: flex; 
  /* 🌟 核心治病代码：均分剩余空间！
     它会自动把左边第一个标签往右推（不再固定死在左侧边缘），
     同时让两个标签之间保持完美的自适应距离，彻底消灭那一大块死白！ */
  justify-content: space-evenly; 

  flex: 1; /* 整体容器依然去自适应抢占左侧所有的剩余宽度 */
  margin-left: 0; 
  margin-bottom: clamp(4px, 1vw, 6px); 
  margin-right: clamp(5px, 2vw, 15px); /* 右侧安全距离微调，给气泡腾出更多悬浮空间 */
}

.stat-pill {
  background: #fff; 
  /* 气泡自身的宽度完全由 padding 动态控制，绝对不再拉伸变形 */
  padding: 3px clamp(12px, 3vw, 20px); 
  border-radius: 12px;
  font-size: clamp(9px, 2.2vw, 12px); 
  font-weight: 700; 
  color: var(--text-main);

  display: flex; 
  align-items: center; 
  justify-content: center; 
  gap: 6px;
  white-space: nowrap; 
}

/* --- 🌟 纯 CSS 日历图标修复 --- */
.css-icon-calendar { 
  width: 12px; height: 12px; 
  border: 1.5px solid var(--text-main); 
  border-top: 3.5px solid var(--text-main); 
  border-radius: 2px; 
  display: inline-block; 
  vertical-align: middle; 
  position: relative; 
  box-sizing: border-box; 
  margin-top: -2px; 
  flex-shrink: 0; /* 🌟 防挤压锁 */
}
.css-icon-calendar::after { 
  content: ''; position: absolute; 
  width: 1px; height: 1px; background: var(--text-main); 
  top: 1.5px; left: 1.5px; 
  box-shadow: 
    2.5px 0 0 var(--text-main), 
    5px 0 0 var(--text-main), 
    0 2.5px 0 var(--text-main), 
    2.5px 2.5px 0 var(--text-main), 
    5px 2.5px 0 var(--text-main); 
}

/* --- 🌟 纯 CSS 评论气泡图标修复 --- */
.css-icon-comment { 
  width: 14px; height: 10px; 
  border: 1.5px solid var(--text-main); 
  border-radius: 3px; 
  display: inline-block; 
  vertical-align: middle; 
  position: relative; 
  box-sizing: border-box; 
  margin-top: -2px; 
  flex-shrink: 0; /* 🌟 防挤压锁 */
}
.css-icon-comment::after { 
  content: ''; position: absolute; bottom: -4px; left: 2px; width: 0; height: 0; 
  border-left: 2px solid transparent; border-right: 2px solid transparent; 
  border-top: 3.5px solid var(--text-main); 
}
.css-icon-comment::before { 
  content: ''; position: absolute; width: 1.5px; height: 1.5px; 
  background: var(--text-main); border-radius: 50%; top: 50%; left: 50%; 
  transform: translate(-50%, -50%); 
  box-shadow: -3.5px 0 0 var(--text-main), 3.5px 0 0 var(--text-main); 
}

.tabs-group { 
  display: flex; gap: clamp(2px, 1vw, 4px); align-items: flex-end; 
  flex-shrink: 0; /* 🌟 保护右侧标签不被左边挤变形 */
}

.tab-item {
  background-color: var(--board-bg);
  padding: 6px clamp(5px, 1.8vw, 14px) 12px; 
  margin-bottom: -8px; /* 强制下潜插进白板，消除黑缝 */
