  z-index: 10; 
  overflow: hidden;
}

/* ---------------- 左侧：头像区与装饰 ---------------- */
.left-zone {
  width: 44%; 
  flex: none;
  position: relative;
  display: flex; justify-content: center; align-items: center;
}
