  position: relative; z-index: 2;
}

/* 🌟 手绘感对话气泡修复（彻底解决过宽拉伸问题） */
.decor-bubble {
  position: absolute; z-index: 3;
  background: #fff; border: 1.5px solid var(--text-main);
  border-radius: 50% 50% 50% 10% / 60% 60% 40% 40%; 
  padding: 4px 2px; font-size: clamp(10px, 2.5vw, 12px);
  font-weight: 600; color: var(--text-main); font-style: italic;

  /* 🌟 核心防变型线：锁定气泡宽度，不允许随父容器无脑拉长，并让文字保持居中 */
  width: clamp(45px, 32%, 65px); 
  aspect-ratio: 1.4 / 1; 
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
}
.bubble-top { top: 0; right: 0; transform: rotate(5deg); }
.bubble-bottom { 
  bottom: 5%; left: 10%; transform: rotate(-5deg); 
  border-radius: 50% 50% 10% 50% / 40% 40% 60% 60%; 
}

/* 图片猫爪控制器 */
