.b-item { flex: 1; height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; gap: clamp(2px, 1vw, 4px); }
.b-img { width: 100%; height: clamp(36px, 12vw, 48px); object-fit: cover; border-radius: 10px; background-color: var(--img-bg, #e8e8e8); }
