}

.avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.user-text {
  font-size: clamp(13px, 4vw, 18px);
  font-weight: 700;
  color: var(--text-color); 
  white-space: nowrap;
}

/* 矢量爱心配置 */
.css-heart-icon {
  position: relative;
  width: clamp(12px, 3.5vw, 16px);
  height: clamp(12px, 3.5vw, 16px);
  background-color: var(--heart-color); 
  transform: rotate(-45deg);
  margin-right: clamp(4px, 2vw, 8px);
  flex-shrink: 0;
}

.css-heart-icon::before,
.css-heart-icon::after {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  background-color: var(--heart-color); 
  border-radius: 50%;
}
.css-heart-icon::before { top: -50%; left: 0; }
.css-heart-icon::after { top: 0; left: 50%; }

/* ================= 3. 下半部分：四连排图库 ================= */
.retro-bottom {
