  object-fit: cover;
  border-radius: clamp(6px, 2vw, 10px);
  background-color: var(--img-placeholder); 
  display: block;
}

/* ================= 1. 响应式主容器 ================= */
.mz-corner-widget {
    position: relative;
    width: 100%;
    height: 100%;
    background: transparent;
    overflow: hidden; 
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
    box-sizing: border-box;
}

/* ================= 2. 侧边悬浮气泡通用架构 ================= */
.glass-box {
    position: absolute;
    /* 🚨 核心改动：最大与最小宽度整体缩小一点点，显得更精致 */
    width: clamp(75px, 24vw, 110px); 
    padding: clamp(6px, 1.8vw, 9px) clamp(8px, 1.8vw, 11px);
    border-radius: 14px;

