.strip-text { font-size: clamp(9px, 2.5vw, 11.5px); color: var(--strip-text-color, #555555); white-space: nowrap; letter-spacing: 0.3px; font-weight: 600; text-align: center; }

/* ================= 全局底座防扭曲 ================= */
.mz-chat-gallery-4x4 {
