}

/* ================= 独立底层：背景图片 ================= */
.bg-image-layer { position: absolute; inset: 0; z-index: 0; }
.bg-image-layer img { width: 100%; height: 100%; object-fit: cover; display: block; }

/* ================= 独立中层：颜色与毛玻璃遮罩 ================= */
.bg-mask-layer { position: absolute; inset: 0; z-index: 1; }

/* ================= 核心流式内容层 ================= */
.vibe-inner {
  position: relative; z-index: 2; 
