  --text-main: #222222;
  --text-sub: #666666;
  --divider-color: #e5e5e5;
  --stamp-bg: #f9f9f9;
}

/* ================= 核心流式内容层 ================= */
.receipt-inner {
  height: 100%; width: 100%;
  display: flex; flex-direction: column; 
  justify-content: space-between;
  padding: clamp(12px, 4vw, 16px); 
  box-sizing: border-box;
}

/* ================= 1. 头部区域 ================= */
.receipt-header { display: flex; flex-direction: column; gap: 2px; }
.rc-title { font-size: clamp(11px, 3.2vw, 13px); font-weight: 800; color: var(--text-main); letter-spacing: 0.5px; }
.rc-serial { font-size: clamp(9px, 2.5vw, 10px); color: var(--text-sub); }

.rc-divider { height: 1px; background-color: var(--divider-color); width: 100%; margin: 4px 0; }
.rc-divider.dashed { background-color: transparent; border-bottom: 1.5px dashed var(--divider-color); height: 0; }

/* ================= 2. 主体区（自适应流水线布局） ================= */
.receipt-body { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex: 1; min-height: 0; }

.receipt-info { flex: 1; display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.info-item { display: flex; align-items: center; gap: 4px; font-size: clamp(10px, 2.8vw, 11px); line-height: 1.3; }
.item-label { color: var(--text-sub); font-weight: 700; flex-shrink: 0; }
.item-val { color: var(--text-main); font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* 🌟 2x2 极精致正方形邮票小框 */
.receipt-stamp {
  width: clamp(42px, 12vw, 52px); 
  height: clamp(42px, 12vw, 52px);
  background-color: var(--stamp-bg);
  border: 1px solid var(--divider-color);
  padding: 3px; border-radius: 4px;
  box-sizing: border-box; flex-shrink: 0;
}
.receipt-stamp img { width: 100%; height: 100%; object-fit: cover; border-radius: 2px; display: block; }

/* ================= 3. 尾部区域 ================= */
.receipt-footer { display: flex; align-items: flex-end; justify-content: space-between; gap: 6px; }

.barcode-area { flex: 0.7; }
/* 🌟 纯 CSS 线性渐变绘制的高清矢量条形码 */
.css-barcode {
  width: 100%; height: clamp(16px, 5vw, 22px);
  background: repeating-linear-gradient(
    90deg,
    var(--text-main),
    var(--text-main) 1.5px,
    transparent 1.5px,
    transparent 3.5px
  );
  opacity: 0.8;
}

.receipt-total { display: flex; flex-direction: column; align-items: flex-end; gap: 1px; flex-shrink: 0; }
.total-label { font-size: clamp(8px, 2.2vw, 9px); font-weight: 700; color: var(--text-sub); }
.total-val { font-size: clamp(11px, 3.2vw, 13px); font-weight: 800; color: var(--text-main); }

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  width: 100%;
  height: 100%;
  background: transparent !important;
}
.wrap {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  position: relative;
}
.avatar-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  align-self: center;
}
.left .bubble,
.left .avatar {
  animation: beatSlowLeft 3.2s ease-in-out infinite;
}
.right .bubble,
.right .avatar {
  animation: beatSlowRight 3.2s ease-in-out infinite;
}
.bubble {
  --bubbleBg: #eeeeee;
  font-size: 11px;
  padding: 4px 8px;
  border-radius: 8px;
  border: none;
  position: relative;
  white-space: nowrap;
  transform-origin: center;
}
.bubble::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 4px solid transparent;
  border-top-color: var(--bubbleBg);
}
.avatar {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  border: 1px solid #ffffff;
  box-shadow: 0 1px 4px rgba(0,0,0,0.08);
  background: #ddd center/cover no-repeat;
  transform-origin: center;
}
.line-center-group {
  display: flex;
  align-items: center;
  gap: 2px;
}
.ecg-left, .ecg-right {
  width: 55px;
  height: 26px;
}
.day-num {
  font-size: 17px;
  font-weight: 500;
  white-space: nowrap;
}
/* 胶囊向下微调，缩短距离 */
.capsule-wrap {
  position: absolute;
  top: 26px;
  left: 50%;
  transform: translateX(-50%);
}
.capsule-text {
  width: auto;
  text-align: center;
  background: #ffffff;
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 12px;
  border: 1px solid;
  white-space: nowrap;
}
/* 底部无背景浅灰小字 */
.footer-text {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 12px;
  color: #bbbbbb;
  white-space: nowrap;
}

@keyframes beatSlowLeft {
  0%, 100% {transform: scale(1);}
  50% {transform: scale(1.06);}
}
@keyframes beatSlowRight {
  0%, 100% {transform: scale(1);}
  40% {transform: scale(1);}
  70% {transform: scale(1.06);}
}

