/* ================= 全局容器 ================= */
.mz-chat-drawer-4x4 {
  width: 100%; height: 100%; position: relative; overflow: hidden;
  aspect-ratio: 1 / 1; 
  border-radius: 28px; box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;

  --bg-base: #f5f5f5;
  --drawer-bg: #e9e9e9;
  --bubble-bg: #ffffff;
  --text-main: #333333;
  --text-sub: #888888;
  --accent-dark: #555555;
}

/* ================= 智能背景层 ================= */
.bg-layer { position: absolute; inset: 0; z-index: 0; border-radius: inherit; }
[data-bg="transparent"] .bg-layer { background: transparent; }
[data-bg="frosted"] .bg-layer { backdrop-filter: blur(25px); -webkit-backdrop-filter: blur(25px); }
[data-bg="frosted"] .bg-layer::before,
[data-bg="semi-color"] .bg-layer::before {
  content: ''; position: absolute; inset: 0; border-radius: inherit;
  background-color: var(--bg-base); opacity: 0.5;
}

/* ================= 核心流式布局 ================= */
.content-layer {
  position: relative; z-index: 1; height: 100%;
  display: flex; flex-direction: column; 
  box-sizing: border-box;
}

/* ================= 1. 顶部状态栏 ================= */
.top-bar { display: flex; justify-content: space-between; align-items: center; padding: clamp(16px, 4.5vw, 24px) clamp(16px, 4.5vw, 24px) clamp(8px, 2vw, 12px) clamp(16px, 4.5vw, 24px); flex-shrink: 0; }
.icon-back { width: 12px; height: 12px; border-left: 2px solid var(--text-main); border-bottom: 2px solid var(--text-main); transform: rotate(45deg); margin-left: 4px; opacity: 0.8; }
.top-right { display: flex; align-items: center; gap: 8px; }
.btn-home { background-color: var(--bubble-bg); width: clamp(24px, 6vw, 30px); height: clamp(24px, 6vw, 30px); border-radius: 6px; display: flex; align-items: center; justify-content: center; }
.btn-home svg { width: 60%; height: 60%; color: var(--accent-dark); }
.tag-pill { background-color: var(--bubble-bg); color: var(--text-main); font-size: clamp(10px, 2.8vw, 12px); font-weight: 700; padding: clamp(4px, 1.2vw, 6px) clamp(10px, 2.5vw, 14px); border-radius: 99px; }

/* ================= 2. 聊天互动区 ================= */
.chat-area {
  flex: 1; display: flex; flex-direction: column; align-items: flex-end; justify-content: center;
  padding: 0 clamp(16px, 4.5vw, 24px); gap: clamp(8px, 2vw, 12px); min-height: 0;
}

/* 音乐气泡卡片 */
.music-card { background-color: var(--bubble-bg); border-radius: 16px; padding: clamp(10px, 2.8vw, 14px); display: flex; gap: clamp(10px, 2.8vw, 14px); align-items: center; max-width: 85%; position: relative; }
.m-cover { width: clamp(48px, 13vw, 60px); height: clamp(48px, 13vw, 60px); border-radius: 10px; overflow: hidden; flex-shrink: 0; background-color: rgba(0,0,0,0.05); }
.m-cover img { width: 100%; height: 100%; object-fit: cover; display: block; }
.m-info { display: flex; flex-direction: column; gap: 2px; justify-content: center; padding-right: 20px; }
.m-title { font-size: clamp(12px, 3.2vw, 14px); font-weight: 800; color: var(--text-main); }
.m-artist { font-size: clamp(10px, 2.5vw, 12px); font-weight: 600; color: var(--text-main); }
.m-logo { display: flex; align-items: center; gap: 4px; font-size: clamp(9px, 2.2vw, 10px); font-weight: 700; color: var(--text-sub); margin-top: 2px; }
.m-logo svg { width: 10px; height: 10px; }

.m-close { position: absolute; top: clamp(8px, 2vw, 12px); right: clamp(8px, 2vw, 12px); width: 18px; height: 18px; background-color: var(--accent-dark); border-radius: 50%; }
.m-close span { position: absolute; top: 50%; left: 50%; width: 8px; height: 1.5px; background-color: #fff; }
.m-close span:first-child { transform: translate(-50%, -50%) rotate(45deg); }
.m-close span:last-child { transform: translate(-50%, -50%) rotate(-45deg); }

/* 输入框群组 */
.input-row { display: flex; align-items: center; gap: 10px; width: 100%; justify-content: flex-end; }
.icon-chevron { width: 10px; height: 10px; border-top: 2.5px solid var(--text-sub); border-right: 2.5px solid var(--text-sub); transform: rotate(45deg); opacity: 0.6; }

.input-box {
  background-color: var(--bubble-bg); border-radius: 99px;
  display: flex; align-items: center;
  padding: clamp(6px, 1.5vw, 8px) clamp(6px, 1.5vw, 8px) clamp(6px, 1.5vw, 8px) clamp(14px, 3.5vw, 20px);
