}

/* 🌟 核心增补：右侧经典呼吸闪烁光标 */
@keyframes i-cursor-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}
.i-cursor { 
  width: 1.5px; height: 14px; background-color: var(--text-main); 
  margin-left: 4px; 
  margin-right: auto; /* 👈 关键点：将右侧的发送按钮撑到输入框最右端 */
  animation: i-cursor-blink 1s infinite; 
}

.btn-send {
  width: clamp(24px, 6vw, 32px); height: clamp(24px, 6vw, 32px);
  background-color: var(--accent-dark); border-radius: 50%;
