  padding: clamp(8px, 2vw, 12px) clamp(16px, 4vw, 20px) clamp(16px, 4vw, 20px) clamp(16px, 4vw, 20px);
  display: flex; flex-direction: column; gap: clamp(10px, 2.5vw, 14px);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.03); flex-shrink: 0;
}
