/* ================= 背景防溢出层 ================= */
.bg-layer { position: absolute; inset: 0; z-index: 0; border-radius: inherit; }
[data-bg="transparent"] .bg-layer { background: transparent; }
[data-bg="frosted"] .bg-layer { backdrop-filter: blur(25px); -webkit-backdrop-filter: blur(25px); }
[data-bg="frosted"] .bg-layer::before,
[data-bg="semi-color"] .bg-layer::before {
  content: ''; position: absolute; inset: 0; border-radius: inherit;
  background-color: var(--bg-color); opacity: 0.5;
}

/* ================= 核心弹性场 ================= */
.content-layer {
  position: relative; z-index: 1; height: 100%;
  display: flex; flex-direction: column; 
  justify-content: space-between; 
  padding: clamp(14px, 4vw, 22px); 
  box-sizing: border-box;
