  /* 【调整】上下内边距缩减，极限放大主图 */
  padding: 10px 14px; 
  display: flex;
  flex-direction: column;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  box-shadow: inset 0 0 0 1px rgba(0,0,0,0.05);
}

/* --- 1. 顶部信息栏 --- */
.header-bar {
  display: flex;
  align-items: center;
  gap: 4px;
  /* 【调整】向下间距缩窄 3px */
  margin-bottom: 5px; 
  height: 26px;
  flex-shrink: 0; 
}

.back-icon {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  margin-left: -10px;
}

.avatar-box {
  width: 26px; 
  height: 26px;
  border-radius: 50%;
  overflow: hidden;
  flex-shrink: 0;
  background-color: #f0f0f0;
}

.avatar-box img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ID 昵称 */
.name-text {
  /* 【调整】字号进一步缩小 */
  font-size: 12px; 
  font-weight: 600;
  color: #333333;
  flex-grow: 1; 
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-left: 2px;
}

/* 关注按钮基础样式 (未关注) */
.follow-btn {
  flex-shrink: 0;
  background-color: transparent;
  border: 1px solid #d0d0d0;
  color: #333333;
  padding: 4px 8px; /* 内边距缩小 */
  /* 【调整】字号进一步缩小 */
  font-size: 10px; 
  font-weight: 500;
  border-radius: 20px; 
  cursor: pointer;
  outline: none;
  white-space: nowrap;
  /* 过渡效果涵盖形变、颜色和边框 */
  transition: transform 0.15s cubic-bezier(0.4, 0, 0.2, 1), 
              color 0.2s ease, 
              border-color 0.2s ease, 
              background-color 0.2s ease;
}

/* 按钮点击瞬间的弹簧缩放效果 */
.follow-btn.clicked {
  transform: scale(0.85);
}

/* 按钮变为【已关注】后的弱化样式 */
.follow-btn.followed-state {
  color: #888888;
  border-color: #ececec;
  background-color: #f8f8f8; /* 微微带点灰底，表示已激活 */
}


/* --- 2. 中间主图区 --- */
.main-image-box {
  flex-grow: 1; 
  width: 100%;
  border-radius: 14px; 
  overflow: hidden;
  background-color: #f5f5f5;
  min-height: 0; 
}

.main-image-box img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}


/* --- 3. 底部签名区 --- */
.footer-text {
  flex-shrink: 0;
  text-align: center;
  /* 【调整】向上间距缩窄 3px */
  margin-top: 5px; 
  /* 【调整】字号进一步缩小 */
  font-size: 10px; 
  color: #888888;
  height: 14px;
  display: flex;
  justify-content: center;
  align-items: center;
  white-space: nowrap;
  overflow: hidden;
}

.sparkle {
  font-size: 11px;
  margin: 0 3px;
  color: #aaaaaa;
}

/* --- 基础重置 --- */
html, body {
  margin: 0;
  padding: 0;
  width: 100vw;
  height: 100vh;
  background: transparent;
  overflow: hidden;
}

* {
  box-sizing: border-box;
}

/* 主容器 (毛玻璃效果) */
.widget-wrapper {
  width: 100%;
  height: 100%;
  background-color: rgba(220, 220, 225, 0.4); 
  backdrop-filter: blur(20px); 
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.2); 
  border-radius: 26px; 
  padding: 14px 12px; 
  display: flex;
  flex-direction: column;
  justify-content: space-between; 
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

/* 统一的字体默认样式 */
