/* ================= 背景渲染层 (强锁50%半透) ================= */
.bg-layer { position: absolute; inset: 0; z-index: 0; }
[data-bg="transparent"] .bg-layer { background: transparent; }
[data-bg="frosted"] .bg-layer { backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); }
[data-bg="frosted"] .bg-layer::before,
[data-bg="semi-color"] .bg-layer::before {
  content: ''; position: absolute; inset: 0;
