/* ================= 专属波点层 ================= */
.bg-dots {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image: 
    radial-gradient(var(--dot-col) 1.5px, transparent 1.5px),
    radial-gradient(var(--dot-col) 1.5px, transparent 1.5px);
  background-position: 0 0, 10px 10px;
  background-size: 24px 24px;
  opacity: 0.12; 
  z-index: -1;
}

/* ================= 左侧区域 ================= */
.left-col {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 1;
  min-width: 0;
}

/* ================= 🌟 极简：紧紧包裹的单线头像框 ================= */
.avatar-wrap {
  width: clamp(60px, 20vw, 85px);
  height: clamp(60px, 20vw, 85px); 
  border-radius: 50%;

  /* 1. 彻底去掉 padding，消灭所有空隙 */
  padding: 0; 

  /* 2. 这就是紧紧包裹在外面的那一条线（半透明黑，不抢风头） */
  border: 1.5px solid rgba(0, 0, 0, 0.15); 

  /* 3. 溢出修剪：保证图片绝对不会超出这条线的边界 */
  overflow: hidden; 

  box-sizing: border-box;
  flex-shrink: 0;
  margin-bottom: clamp(6px, 2vw, 10px);
  display: flex;
  justify-content: center;
  align-items: center;
}

.avatar-wrap img {
  width: 100%; 
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  display: block;

  /* 彻底去掉图片自带的线，只留外层一条线 */
  border: none; 
}

.nickname {
  font-size: clamp(12px, 3.5vw, 14px);
  font-weight: 600;
  color: var(--text-col);
  margin-bottom: clamp(8px, 2.5vw, 12px);
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.day-pill {
  background: var(--frame-bg);
  padding: clamp(6px, 2vw, 8px) clamp(14px, 4vw, 20px);
  border-radius: 999px;
  display: flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  box-sizing: border-box;
}
#valDay {
  font-size: clamp(11px, 3.5vw, 13px);
  font-weight: 600;
  color: var(--text-col);
  opacity: 0.9;
}

.icon-cal {
  position: relative;
  width: 12px; height: 12px;
  border: 1.5px solid var(--text-col);
  border-radius: 3px;
  opacity: 0.8;
  flex-shrink: 0;
  box-sizing: border-box;
  margin-top: 2px;
}
.icon-cal::before {
  content: ''; position: absolute;
  top: 2px; left: -1.5px; right: -1.5px;
  height: 1.5px; background: var(--text-col);
}
.icon-cal::after {
  content: ''; position: absolute;
  top: -3px; left: 2px; width: 1.5px; height: 3px;
  background: var(--text-col);
  box-shadow: 4px 0 0 var(--text-col); 
}

/* ================= 右侧区域 ================= */
.right-col {
  display: flex;
  flex-direction: column;
  justify-content: center;
  z-index: 1;
  min-width: 0;
}

.top-text-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px; 
  margin-bottom: clamp(6px, 2vw, 10px);
  width: 100%;
}
.top-text {
  font-size: clamp(11px, 3vw, 13px);
  font-weight: 600;
  color: var(--text-col);
  letter-spacing: 0.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.deco-line {
  width: 14px; 
  height: 1.5px; 
  background-color: var(--text-col);
  border-radius: 1px;
  opacity: 0.8;
  flex-shrink: 0;
}

.img-frame {
  background: var(--frame-bg);
  padding: clamp(6px, 2vw, 10px);
  border-radius: 16px;
  display: flex;
  gap: clamp(6px, 2vw, 10px);
  height: clamp(120px, 30vw, 140px); 
  width: 100%;
  box-sizing: border-box;
}

.inner-img {
  flex: 1;
  height: 100%;
  border-radius: 8px;
  overflow: hidden;
  background-color: rgba(255,255,255,0.5); 
}
.inner-img img {
  width: 100%; height: 100%;
  object-fit: cover;
  display: block;
}

/* ================= 全局容器 ================= */
.stamp-calendar-widget {
  width: 100%;
  height: 100%;
  padding: clamp(16px, 5vw, 24px);
  box-sizing: border-box;
  border-radius: 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;

  --text-col: #333333;
  --bg-color: rgba(255, 255, 255, 0.6);

  font-family: "Georgia", "Times New Roman", serif; 
  color: var(--text-col);
}

/* ================= 背景模式强制接管 ================= */

/* 1. 毛玻璃模式 */
.stamp-calendar-widget[data-bg-style="frosted"] {
  /* 🚨 核心修改：外壳彻底透明，把颜色交给下方的半透明画板 */
  background-color: transparent !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
}

/* 强制增加一层“半透滤镜”，无论你选什么颜色，都会被强制降低透明度露出毛玻璃 */
.stamp-calendar-widget[data-bg-style="frosted"]::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--bg-color);
  opacity: 0.45; /* 🌟 强制 45% 半透明，数值可自由修改 */
  z-index: -1;
}

/* 2. 全透明模式 */
.stamp-calendar-widget[data-bg-style="transparent"] {
  background-color: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  border: none !important;
}
.stamp-calendar-widget[data-bg-style="transparent"]::before {
  display: none !important; /* 透明模式下隐藏滤镜 */
}


/* ================= 顶部信息区 ================= */
.header-row {
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.date-side {
  font-size: clamp(20px, 6vw, 22px);
  font-weight: 600;
  letter-spacing: 1px;
}

.time-center {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  font-size: clamp(20px, 6vw, 26px);
  font-weight: bold;
  letter-spacing: 1px;
}


/* ================= 列布局：星期 + 邮票 + 几号 ================= */
.cards-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: clamp(8px, 2vw, 14px);
  flex: 1;
}

.day-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between; /* 让上下文字和中间图片均匀分布 */
}

.week-text {
  font-size: clamp(11px, 3vw, 13px);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  opacity: 0.6;
  white-space: nowrap;
}

.date-num {
  font-size: clamp(14px, 4vw, 11px);
  font-weight: 600;
  white-space: nowrap;
}

/* ================= 🌟 真正的图片直接裁剪邮票边缘 ================= */
.stamp-box {
  width: 100%;
  aspect-ratio: 1 / 1.15; 
  /* 不再需要任何背景色和 padding，完全把整个空间交给图片 */

  /* 双层遮罩：
     第一层：实心保护层，死死护住图片正中间不被掏空。
     第二层：打孔层，只在图片最外圈的边缘咬出半圆锯齿。 */
  -webkit-mask-image: 
    linear-gradient(black, black), 
    radial-gradient(circle at 6px 6px, transparent 4px, black 4.5px); 

  -webkit-mask-size: 
    calc(100% - 12px) calc(100% - 12px), /* 保护层收缩 6px，把边缘让出来给打孔层 */
    12px 12px; /* 每个孔洞占据 12px 的空间 */

  -webkit-mask-position: 
    center, 
    -6px -6px; /* 向外偏移 6px，让孔洞圆心绝对精准地压在图片的边缘线上 */

  /* 🚨 核心修复：用 round 属性强制孔洞自动平分宽度，彻底杜绝右边被切平！ */
  -webkit-mask-repeat: 
    no-repeat, 
    round; 

  /* 标准语法兜底 */
  mask-image: linear-gradient(black, black), radial-gradient(circle at 6px 6px, transparent 4px, black 4.5px);
  mask-size: calc(100% - 12px) calc(100% - 12px), 12px 12px;
  mask-position: center, -6px -6px;
  mask-repeat: no-repeat, round;
}

/* 照片完全撑满，并且直接被上面的遮罩啃出锯齿 */
.stamp-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ===================================================
   🌟 4*2 短信恋爱计时器小组件 - 完整精修版 CSS
   =================================================== */

/* ================= 全局容器 (终极毛玻璃 + 防爆自适应) ================= */
.mz-sms-widget {
  width: 100%;
  height: 100%;
  /* 自适应：内外边距使用比例缩放，适配各种屏幕宽度 */
  padding: clamp(12px, 4vw, 16px) clamp(16px, 5vw, 20px);
  box-sizing: border-box;
  border-radius: 24px;
  position: relative;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;

  /* 左 4 右 6 网格布局，自带自适应基因 */
  display: grid;
  grid-template-columns: 4fr 6fr;
  gap: clamp(10px, 3vw, 16px);

  /* 极致毛玻璃三要素：强模糊 + GPU 加速 + 玻璃边缘高光描边 */
  background: transparent; /* 本层彻底透明，交由 ::before 渲染底色 */
  backdrop-filter: blur(15px) saturate(180%);
  -webkit-backdrop-filter: blur(15px) saturate(180%);
  transform: translateZ(0); /* 强制开启硬件加速，防止部分手机毛玻璃失效 */
  border: 1px solid rgba(255, 255, 255, 0.2); /* 玻璃边缘的微弱高光反光 */
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08); /* 柔和的底层投影 */

  /* 变量兜底设定 */
  --theme-bg: #F9F1F2;
  --text-col: #D0B4B5;
  --time-col: #ffffff; 
  --widget-bg: #B4AFB2;

  /* 防爆底层：允许网格内容自由收缩，绝不挤压变形 */
  min-width: 0;
  min-height: 0;
  z-index: 0;
}

/* 🌟 核心修复：独立出来的强行玻璃化底色层 */
.mz-sms-widget::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--widget-bg);
  /* 强制透明度降到 0.5。哪怕后台选了不透光的 Hex 纯色，也会自动变成透光毛玻璃！ */
  opacity: 0.5; 
  z-index: -1; /* 垫在星星和所有内容的最下方 */
}

/* ================= 🌟 满天繁星 (百分比坐标，铺满全屏) ================= */
.decor-star {
  position: absolute;
  background-color: var(--theme-bg);
  -webkit-mask-size: contain; mask-size: contain;
  -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat;
  z-index: 0; /* 确保垫在气泡和头像下面，形成前后的纵深空间感 */
}

/* 实色星星 */
.decor-star.solid {
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z'/%3E%3C/svg%3E");
  mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z'/%3E%3C/svg%3E");
}

/* 镂空星星 */
.decor-star.hollow {
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg' fill='none' stroke='black' stroke-width='2' stroke-linejoin='round'%3E%3Cpath d='M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z'/%3E%3C/svg%3E");
  mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg' fill='none' stroke='black' stroke-width='2' stroke-linejoin='round'%3E%3Cpath d='M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z'/%3E%3C/svg%3E");
}

/* 繁星全屏散落坐标与角度（精心排布，多而不密） */
/* 左半区 */
.star-1 { width: 28px; height: 28px; top: 8%; left: 4%; transform: rotate(-15deg); opacity: 0.9; }
.star-2 { width: 14px; height: 14px; top: 35%; left: 2%; transform: rotate(25deg); opacity: 0.7; }
