/* 中间缝隙与中轴线区 */
.star-5 { width: 16px; height: 16px; top: 12%; left: 38%; transform: rotate(-10deg); opacity: 0.8; }
.star-6 { width: 12px; height: 12px; top: 40%; left: 45%; transform: rotate(15deg); opacity: 0.9; }
.star-7 { width: 20px; height: 20px; bottom: 25%; left: 40%; transform: rotate(-30deg); opacity: 0.6; }
.star-8 { width: 14px; height: 14px; bottom: 5%; left: 30%; transform: rotate(10deg); opacity: 0.8; }
/* 右半区 */
.star-9 { width: 22px; height: 22px; top: 6%; left: 65%; transform: rotate(15deg); opacity: 0.6; }
.star-10 { width: 26px; height: 26px; top: 16%; right: 6%; transform: rotate(35deg); opacity: 0.7; }
.star-11 { width: 12px; height: 12px; top: 45%; right: 3%; transform: rotate(-15deg); opacity: 0.8; }
.star-12 { width: 18px; height: 18px; bottom: 42%; right: 28%; transform: rotate(-10deg); opacity: 0.7; }
.star-13 { width: 24px; height: 24px; bottom: 22%; right: 8%; transform: rotate(15deg); opacity: 0.9; }
.star-14 { width: 14px; height: 14px; bottom: 12%; right: 45%; transform: rotate(25deg); opacity: 0.8; }
.star-15 { width: 16px; height: 16px; bottom: 4%; right: 4%; transform: rotate(-40deg); opacity: 0.8; }


/* ================= 左侧区域 (标签 + 放大头像) ================= */
.left-col {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center; /* 确保左侧所有组件严格中轴线对齐 */
  z-index: 1;
  min-width: 0; 
}

.pill-tag {
  background: var(--theme-bg);
  color: var(--text-col);
  padding: 6px 16px;
  border-radius: 999px;
  font-size: clamp(11px, 3.5vw, 13px); /* 字体自适应缩放 */
  font-weight: 600;
  letter-spacing: 1px;
  white-space: nowrap;

  /* 防文本过长撑爆核心 */
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  box-sizing: border-box;
}

.avatar-group {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
}
.avatar {
  /* 头像随屏幕弹性缩放，锁定最大 68px 维持手账精致感 */
  width: clamp(48px, 16vw, 68px); 
  height: auto;
  aspect-ratio: 1 / 1; 
  border-radius: 50%;
  background: #fff;
  border: 2px solid var(--theme-bg);
  box-shadow: 0 4px 10px rgba(0,0,0,0.05);
  overflow: hidden;
  flex-shrink: 0;
}
.avatar img {
  width: 100%; height: 100%; object-fit: cover;
}
.avatar:nth-child(2) {
  margin-left: -20%; /* 使用百分比负边距，任何尺寸下重叠比例都完全一致 */
}


/* ================= 右侧区域 (居中时间 + 瘦身气泡) ================= */
.right-col {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-end; /* 右侧对话气泡整体靠右对齐 */
  z-index: 1;
  min-width: 0; 
}

/* 短信及实时时钟：相对于右半部分绝对居中 */
.header-time {
  align-self: center; 
  text-align: center;
  margin-top: -4px;
}
.time-title { 
  font-size: clamp(12px, 3.5vw, 14px); 
  font-weight: 600; 
  letter-spacing: 2px; 
  margin-bottom: 2px;
  color: var(--time-col); 
}
.time-clock { 
  font-size: clamp(12px, 3.5vw, 12px); 
  font-weight: 500; 
  letter-spacing: 1px;
  color: var(--time-col); 
  opacity: 0.75; /* 核心：利用透明度，无论换什么主色，时间永远比短信标题淡一点点 */
}

/* 聊天气泡列阵 */
.chat-bubbles {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: clamp(6px, 2vw, 10px); 
  width: 100%;
  margin-bottom: 4px;
}
.bubble {
  background: var(--theme-bg);
  color: var(--text-col);
  padding: clamp(6px, 2vw, 8px) clamp(12px, 3.5vw, 16px); /* 瘦身内边距，更秀气 */
  border-radius: 999px;
  font-size: clamp(11px, 3vw, 13px);
  font-weight: 600;
  width: fit-content;

  /* 气泡自适应防爆：文字太长自动切断展示省略号，绝不撑变形组件 */
  max-width: 100%; 
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  box-sizing: border-box;
}


/* ================= 底部短消息输入栏 ================= */
.input-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: clamp(28px, 8vw, 32px); /* 高度自适应设备 */
}

/* 独立加号按钮 */
.plus-btn {
  height: 100%;
  aspect-ratio: 1 / 1; /* 锁定完美正圆 */
  background: var(--theme-bg);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.icon-plus {
