}
.icon-plus::before { top: 50%; left: 0; right: 0; height: 2px; transform: translateY(-50%); }
.icon-plus::after { left: 50%; top: 0; bottom: 0; width: 2px; transform: translateX(-50%); }

/* 胶囊框本体 */
.input-bar {
