.fp-img {
  /* 占宽 90%，剩下 10% 交给 margin 绝对平分 */
  width: 90%; 
  aspect-ratio: 1 / 1; /* 完美正方形 */

  /* 上边距 5%，左右强制对半切，下边距为 0 */
  margin: 5% auto 0 auto; 

  object-fit: cover;
  border-radius: 2px; 
  background: rgba(0,0,0,0.04);
  /* 照片内部的细线也同步使用自定义线条颜色，保持整体统一 */
