  border-left: 2px solid var(--theme-color);
  transform: rotate(-45deg);
  margin-top: 2px;
}

.header-title {
  color: var(--theme-color); 
  font-size: 18px;
  font-weight: 500;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 8px; 
}

.btn-select {
  background-color: var(--btn-bg);
  color: var(--theme-color);
  font-size: 14px;
  font-weight: 500;
  padding: 5px 12px;
  border-radius: 22px; 
  transition: background-color 0.4s ease, color 0.4s ease;
}

/* 灰色圆形底框 */
.btn-more {
  background-color: var(--btn-bg);
  color: var(--theme-color);
  font-size: 14px;
  font-weight: 1000;
  letter-spacing: 1px;
  width: 30px; 
  height: 30px;
  border-radius: 50px; 
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.4s ease, color 0.4s ease;
}

/* 三个点定位微调 */
.btn-more span {
  position: relative;
  top: -4px;  
  left: 1px;  
}

/* ================= 文案区域 ================= */
.album-text {
  color: var(--text-main);
  font-size: 14px;
  line-height: 1.5;
  /* 🌟 边距改为百分比 */
  padding: 0 5%; 
  flex: 1; 
  transition: color 0.4s ease;
  display: flex;
  flex-direction: column;
}

/* 垂直空间弹性压缩配置 */
.album-text::before {
  content: "";
  flex: 3;
}

.album-text::after {
  content: "";
  flex: 7;
}

/* ================= 六宫格图片区 ================= */
.album-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr); 
  /* 🌟 图片间距也可以用一点点百分比，或者保持小像素防止挤压 */
  gap: 4px; 
  /* 🌟 核心修复 3：底部留白全部改为百分比，完美适配各种细长或方形屏幕 */
  padding: 0 5% 10% 5%;  
}

.grid-img {
  width: 100%;
  aspect-ratio: 1 / 1; 
  border-radius: 0px; 
  background-color: #f5f5f5;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.dark-mode .grid-img {
