body { 
  margin: 0; padding: 0; 
  box-sizing: border-box; 
  font-family: -apple-system, "PingFang SC", sans-serif; 
}

/* ==================
   【核心修復】限制漸變動畫範圍，防止毛玻璃閃爍
   ================== */
:root {
  /* 禁用全局畫面的截圖漸變 */
  view-transition-name: none !important;
}
.massive-gallery {
  /* 告訴瀏覽器：只准對畫廊這個區塊進行無縫漸變 */
  view-transition-name: gallery-transition;
}

/* ==================
   基礎容器與變數應用
   ================== */
.widget {
  width: 100%; height: 100%;
  border-radius: 30px;
  overflow: hidden;
  --theme: #a6bced; 

  background: var(--bg-color);
  backdrop-filter: var(--bg-blur);
  -webkit-backdrop-filter: var(--bg-blur);
  box-shadow: var(--widget-border);
  color: var(--text-color);
  transition: background 0.3s ease, backdrop-filter 0.3s ease, color 0.3s ease;
}

/* ==================
   [▶︎] 文字風格變數 (Text Styles)
   ================== */
/* 0. 亮色發光版 */
.widget.text-style-0 {
  --text-color: #f5f5f5;
  --text-glow: 0 1px 3px rgba(0,0,0,0.4), 0 0 8px rgba(0,0,0,0.2);
  --icon-glow: drop-shadow(0 1px 2px rgba(0,0,0,0.4));
}
/* 1. 暗色版 (黑字 + 極微弱白霧保護) */
.widget.text-style-1 {
  --text-color: #111;
  --text-glow: 0 1px 2px rgba(255, 255, 255, 0.4), 0 0 6px rgba(255, 255, 255, 0.2);
  --icon-glow: drop-shadow(0 0 2px rgba(255, 255, 255, 0.4));
}

/* ==================
   [✿] 背景材質變數 (Background Styles)
   ================== */
/* 0. 全透明 */
.widget.bg-style-0 {
  --bg-color: transparent;
  --bg-blur: blur(0px);
  --widget-border: none;
  --control-bg: color-mix(in srgb, var(--theme) 40%, rgba(255,255,255,0.7));
}
/* 1. 毛玻璃 */
.widget.bg-style-1 {
  --bg-color: rgba(255, 255, 255, 0.15);
  --bg-blur: blur(25px);
  --widget-border: inset 0 0 0 1px rgba(255, 255, 255, 0.3);
  --control-bg: color-mix(in srgb, var(--theme) 60%, transparent);
}

/* ==================
   共用排版樣式
   ================== */
.main-panel {
  width: 100%; height: 100%;
  padding: 16px; 
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 14px; 
}

/* 文字發光與顏色漸變 */
.user-text, .time-block, .info-lines {
  text-shadow: var(--text-glow);
  transition: text-shadow 0.2s ease, color 0.2s ease;
}

/* 1. 頂部佈局 */
.top-bar {
  display: flex; justify-content: space-between; align-items: center;
}
.user-profile {
  display: flex; align-items: center; gap: 10px;
}
.avatar {
  width: 50px; height: 50px; border-radius: 50%; flex-shrink: 0; 
  background-color: #fff; background-position: center; background-size: cover;
  border: 2px solid rgba(255,255,255,0.9);
  box-shadow: 0 4px 10px rgba(0,0,0,0.15), 0 0 12px rgba(255,255,255,0.6);
}
.user-text { display: flex; flex-direction: column; gap: 2px; }
.name { font-size: 16px; font-weight: 900; letter-spacing: 0.5px; }
.sub { font-size: 11px; font-weight: 600; opacity: 0.85; }

.time-block {
  display: flex; align-items: baseline; gap: 4px; text-align: right;
}
.time-block #timeEl { 
  font-size: 28px; font-weight: 900; letter-spacing: 1px; 
  font-variant-numeric: tabular-nums; 
}
.time-block .am-pm { font-size: 14px; font-weight: bold; opacity: 0.8; }

/* 2. 中間 巨幅畫廊 */
.massive-gallery {
  flex: 1; display: flex; gap: 12px; width: 100%;
}
.photo {
  flex: 1; height: 100%; border-radius: 20px;
  background-color: rgba(255,255,255,0.2);
  background-position: center; background-size: cover;
  border: 2px solid rgba(255,255,255,0.6);
  box-shadow: 0 6px 16px rgba(0,0,0,0.12);
  cursor: pointer;
}

/* 3. 底部佈局 */
.bottom-bar {
  display: flex; justify-content: space-between; align-items: flex-end;
}
.info-lines {
  display: flex; flex-direction: column; gap: 6px;
}
.line { 
  font-size: 13px; display: flex; align-items: center; gap: 6px; font-weight: 700; 
}
.line .icon { 
  font-size: 16px; text-shadow: none; 
  filter: var(--icon-glow); 
  transition: filter 0.3s ease;
}
.line .label { opacity: 0.8; font-weight: 600; font-size: 12px; }
.line .val { opacity: 1; }

.controls {
  display: flex; flex-direction: column; align-items: flex-end; gap: 8px;
}
.search-bar {
  background: var(--control-bg); 
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  padding: 6px 14px; border-radius: 20px;
  font-size: 12px; font-weight: bold;
  box-shadow: 0 4px 10px rgba(0,0,0,0.08);
  transition: background 0.3s ease;
}
.icons-row { display: flex; gap: 8px; }
.icon-circle {
  width: 32px; height: 32px; border-radius: 50%;
  background: var(--control-bg); 
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  display: flex; justify-content: center; align-items: center;
  font-size: 13px; font-weight: bold;
  box-shadow: 0 4px 10px rgba(0,0,0,0.08);
  transition: background 0.3s ease, transform 0.1s;
}
.icon-circle:active { transform: scale(0.9); }

/* --- Global Styles & Variables --- */
:root {
    --text-primary: #000;
    --text-secondary: #333;
    --text-tertiary: #888;
    --placeholder-color: #aaa; /* Color for search placeholder */
    --bg-blur: rgba(255, 255, 255, 0.7);
    --icon-bg: rgba(255, 255, 255, 0.85);
    --weekday-bg: rgba(255, 255, 255, 0.55);
    --weekday-active-bg: rgba(175, 175, 192, 0.42);
}

body { margin: 0; font-family: var(--font-main); background: transparent; height: 100%; width: 100%; }

.widget-container {
    width: 100%; height: 100%; box-sizing: border-box;
    display: flex; flex-direction: column;
    position: relative; background: transparent;
}

/* --- Background Card --- */
.background-card {
    position: absolute; z-index: -1;
    top: 98px; left: 0; right: 0; bottom: 0;
    background: var(--bg-blur); border-radius: 24px;
    backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.2);
}

/* --- Section 1: Header --- */
.header-section {
    display: flex; align-items: flex-start; gap: 16px;
    flex-shrink: 0; padding: 16px 16px 12px 16px;
}
.avatar-container { position: relative; flex-shrink: 0; }
.avatar { width: 60px; height: 60px; border-radius: 50%; object-fit: cover; }
.camera-icon-bg {
    position: absolute; bottom: -2px; right: -4px;
    background-color: var(--icon-bg); border-radius: 50%;
    width: 24px; height: 24px; display: flex; align-items: center; justify-content: center;
}
.camera-icon { width: 14px; height: 14px; color: var(--text-primary); }

.info-section { flex-grow: 1; display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.user-id { font-size: 20px; font-weight: 600; color: var(--text-primary); }

.weekday-row {
    display: flex; align-items: center; background: var(--weekday-bg);
    border-radius: 50px; padding: 4px;
    border: 0.5px solid rgba(255, 255, 255, 0.8);
}
.day {
    flex: 1; text-align: center; font-size: 11px;
    font-weight: 500; color: #9999aa; letter-spacing: 0.3px;
    padding: 4px 0; border-radius: 50px; cursor: pointer;
    transition: all 0.18s ease; user-select: none;
}
.day.active { background: var(--weekday-active-bg); color: #555565; font-weight: 600; }

/* --- Wrapper for card content --- */
.card-content-wrapper {
    flex-grow: 1; display: flex; flex-direction: column;
    justify-content: space-between; padding: 16px; min-height: 0;
}

/* --- Main Content Layout --- */
.main-content { display: flex; flex-direction: column; gap: 16px; }
.row { display: flex; justify-content: space-between; align-items: center; }

.icon-and-text { display: flex; align-items: center; gap: 12px; }
.icon-bg { width: 32px; height: 32px; border-radius: 50%; background-color: var(--icon-bg); display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.headphone-icon, .food-icon { width: 18px; height: 18px; color: var(--text-primary); }

.music-text { font-size: 14px; color: var(--text-secondary); font-weight: 500; }
.song-title { font-weight: 600; color: var(--text-primary); }

.stacked-text { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; }
.weather-info { display: flex; align-items: center; gap: 4px; font-size: 14px; color: var(--text-secondary); font-weight: 500; }
.weather-icon { width: 20px; height: 20px; }
.weather-temp { font-weight: 600; color: var(--text-primary); }
.caption { color: var(--text-primary); font-weight: 600; font-size: 14px; }

.time-status, .now-status { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--text-tertiary); }
.check-icon { width: 20px; height: 20px; background-color: #333; color: #fff; border-radius: 50%; padding: 3px; box-sizing: border-box; }
.circle-icon { width: 18px; height: 18px; color: var(--text-tertiary); }

/* --- [NEW] Search Bar Styles --- */
.search-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background-color: #fff;
    border: 1px solid #ddd;
    border-radius: 50px;
    padding: 5px 12px;
    margin-top: 12px;
}
.search-text {
    font-size: 14px;
    color: var(--placeholder-color);
    flex-grow: 1;
}
.search-icon {
    width: 16px;
    height: 16px;
    stroke: var(--placeholder-color);
    flex-shrink: 0;
}

/* --- Footer: Image Grid --- */
.image-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 12px; }
.grid-item { aspect-ratio: 1 / 1; border-radius: 16px; overflow: hidden; background-color: #eee; }
.grid-item img { width: 100%; height: 100%; object-fit: cover; }

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%;
  height: 100%;
  background: transparent;
  font-family: -apple-system, "PingFang SC", "Helvetica Neue", sans-serif;
  overflow: hidden;
}

.wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 4px;
}

/* ========== 頭像 + 耳機線 ========== */
.head {
  position: relative;
  width: 100%;
  height: 32%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding-top: 2px;
}

.avatars {
  display: flex;
  gap: 0;
  z-index: 2;
  position: relative;
}

.av {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  object-fit: cover;
  border: 2.5px solid #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,.18);
  background: #eee;
}

/* 兩個頭像互相疊壓 */
.av1 { margin-right: -10px; z-index: 2; }
.av2 { z-index: 1; }

.cords {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 160px;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

.together-text {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  font-size: 11px;
  color: #888;
  white-space: nowrap;
  letter-spacing: .3px;
  z-index: 3;
  text-shadow: 0 1px 2px rgba(255,255,255,.7);
}
.together-text #together {
  color: #ff5a7a;
  font-weight: 700;
}

/* ========== iPod 本體（豎長方形） ========== */
.ipod {
  flex: 1;
  width: 68%;
  max-width: 200px;
  background: #fff;
  border-radius: 14px;
  padding: 10px 9px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,1),
    inset 0 -2px 6px rgba(0,0,0,.04),
    0 6px 18px rgba(0,0,0,.18),
    0 1px 3px rgba(0,0,0,.08);
  border: 1px solid rgba(0,0,0,.06);
}

.screen {
  background: linear-gradient(180deg, #f4f6f8 0%, #e7ecef 100%);
  border-radius: 3px;
  padding: 4px 6px;
  flex: 0 0 42%;
  display: flex;
  flex-direction: column;
  gap: 3px;
  box-shadow:
    inset 0 1px 3px rgba(0,0,0,.18),
    inset 0 -1px 0 rgba(255,255,255,.6);
  color: #333;
  border: 1px solid #c8ccd0;
}

.screen-top {
  display: flex;
  justify-content: space-between;
  font-size: 8px;
  font-weight: 700;
  border-bottom: 1px solid rgba(0,0,0,.12);
  padding-bottom: 2px;
  color: #444;
}

.np {
  display: flex;
  gap: 6px;
  flex: 1;
  align-items: center;
  min-height: 0;
}

.cover {
  width: 40px;
  height: 40px;
  border-radius: 2px;
  object-fit: cover;
  box-shadow: 0 1px 3px rgba(0,0,0,.3);
  background: #888;
  flex-shrink: 0;
}

.info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.song { font-size: 10px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.artist { font-size: 8px; color: #666; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.bottom-bar { display: flex; align-items: center; gap: 4px; font-size: 7px; color: #555; }
.bar { flex: 1; height: 3px; background: rgba(0,0,0,.1); border-radius: 2px; overflow: hidden; }
.bar-fill { height: 100%; width: 30%; background: linear-gradient(90deg, #4a9eff, #2b7de8); border-radius: 2px; transition: width .3s linear; }

.wheel {
  flex: 1;
  position: relative;
  aspect-ratio: 1;
  margin: 0 auto;
  max-height: 100%;
  background: radial-gradient(circle at 30% 25%, #ffffff 0%, #f0f0f2 50%, #d8d8dc 100%);
  border-radius: 50%;
  box-shadow:
    inset 0 2px 4px rgba(255,255,255,1),
    inset 0 -3px 6px rgba(0,0,0,.08),
    0 1px 3px rgba(0,0,0,.12);
  display: flex;
  align-items: center;
  justify-content: center;
}

.wheel-label.menu {
  position: absolute; top: 7%;
  font-size: 8px; font-weight: 700;
  color: #888; letter-spacing: 1px;
  user-select: none;
}

.wheel-btn {
  position: absolute;
  width: 18%; height: 18%;
  background-repeat: no-repeat;
  background-position: center;
  background-size: 75% 75%;
  cursor: pointer;
  opacity: .55;
  transition: opacity .15s, transform .1s;
}
.wheel-btn:active { transform: scale(.88); opacity: .9; }

.wheel-btn.prev {
  left: 8%;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='%23555' d='M6 6h2v12H6zm3.5 6l8.5 6V6z'/></svg>");
}
.wheel-btn.next {
  right: 8%;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='%23555' d='M16 6h2v12h-2zM6 18l8.5-6L6 6z'/></svg>");
}
.wheel-btn.play {
  bottom: 7%;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='%23555' d='M4 5h3v14H4zm6 0v14l11-7z'/></svg>");
}

.center {
  width: 38%; height: 38%;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #ffffff 0%, #f5f5f7 60%, #e0e0e4 100%);
  box-shadow:
    inset 0 1px 2px rgba(255,255,255,1),
    inset 0 -1px 2px rgba(0,0,0,.08),
    0 1px 3px rgba(0,0,0,.18);
  cursor: pointer;
  transition: transform .1s;
}
.center:active { transform: scale(.94); }
